import React from "react";

export function StatusBadge({
  status,
}: {
  status: string;
}) {
  const variant =
    status === "ΚΑΤΑΧΩΡΗΘΗΚΕ" || status === "ΕΓΚΡΙΘΗΚΕ"
      ? "success"
      : status === "ΕΚΚΡΕΜΕΙ"
      ? "warning"
      : "danger";

  return (
    <span
      className={`badge text-uppercase bg-${variant}`}
      style={{ letterSpacing: "0.02em" }}
    >
      {status}
    </span>
  );
}
